/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import { loadFont as loadSans } from "@remotion/google-fonts/Figtree";
import {
  Children,
  cloneElement,
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  isValidElement,
  type ReactElement,
  type ReactNode,
  type Ref,
  useCallback,
  useContext,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  getRemotionEnvironment,
  Interactive,
  type InteractiveBaseProps,
  type InteractiveTransformProps,
  type InteractivitySchema,
  Sequence,
  type SequenceControls,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

/**
 * One object in a scene — a card, a step, a message, a photo — handed to
 * whoever is editing the scene.
 *
 * A scene draws its objects itself: it knows where each one is on every frame.
 * Remotion Studio wants each one as something it can select, outline and edit
 * on its own. `Item` is the seam between the two. The scene wraps the root
 * element of each object in it:
 *
 *   <Item key={i} index={k}>
 *     <div style={…}>…</div>
 *   </Item>
 *
 * With nothing above it — which is every `shadcn add` install and every render
 * on the site — it returns that element untouched: no wrapper, no extra DOM, no
 * behaviour. Inside a Studio Element, an `ItemHost` above it gets the element
 * and the object's index, and can put it inside the object's own `<Sequence>`
 * with the selection outline on that exact node, so the outline moves with the
 * object for its whole animation.
 */
type ItemHost = (index: number, node: ReactElement) => ReactNode;

const ItemHostContext = createContext<ItemHost | null>(null);

const ItemHostProvider = ItemHostContext.Provider;

function Item({
  index,
  primary = true,
  children,
}: {
  /** Which of the scene's objects this is, in the order its props list them. */
  index: number;
  /**
   * False on every copy but one, for a scene that draws the same object more
   * than once (a looping rail): an object has one outline.
   */
  primary?: boolean;
  children: ReactElement;
}): ReactNode {
  const host = useContext(ItemHostContext);
  return host && primary ? host(index, children) : children;
}

const toRgb = converter("rgb");

const BLACK: Rgb = { mode: "rgb", r: 0, g: 0, b: 0, alpha: 1 };

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function parseColor(c: string): Rgb {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `parseColor cannot resolve CSS variable "${s}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (isDev()) {
      console.warn(`parseColor could not parse "${s}"; using black.`);
    }
    return { ...BLACK };
  }

  return { mode: "rgb", r: rgb.r, g: rgb.g, b: rgb.b, alpha: rgb.alpha ?? 1 };
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    interpolate([resolveColorString(a), resolveColorString(b)], "oklch")(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * A rail of cards flicked sideways across a tilted plane.
 *
 * The cards do not crawl past on a loop. They are *flicked* — the rail leaves at
 * speed, decelerates for well over a second, and comes to rest one card further
 * along, the way a carousel behaves under a thumb rather than under a timer. A
 * title holds the top of the frame and does not move with them.
 *
 * ## The plane is tilted, and that is the whole look
 *
 * The rail is not flat to the camera. Measured on the card edges of a recording,
 * the horizontal scale grows **0.000825 per pixel of height** about the frame's
 * own centre line — the bottom of a card is 22% wider than its top — while
 * horizontals stay horizontal and the type stays upright. That is a plane
 * rotated about a horizontal axis under perspective, and it is why a row of
 * plain rectangles reads as a surface receding into the frame.
 *
 * The three numbers that describe it are `DEPTH`, `TILT` and `HORIZON`, and they
 * are deliberately separate from the card metrics: change the card size and the
 * plane does not move.
 *
 * ## The flick is measured, not eased
 *
 * `FLICK` is the curve off the recording — it peaks at 29px a frame three frames
 * in and is still moving at 2px a frame a second later. No standard ease has that
 * tail; a cubic-out arrives four times too early and a spring overshoots
 * something that never overshoots.
 */

const { fontFamily: SANS } = loadSans("normal", {
  weights: ["400", "500", "600", "700"],
  subsets: ["latin"],
});

/* ─────────────────────────────────────────────────────────────────────────
   The stage, in the recording's own 714 × 396 pixels
   ───────────────────────────────────────────────────────────────────────── */

const REF_W = 714;
const REF_H = 396;

/** Title: cap height and baseline, measured on its own ink. */
const HEAD_CAP = 20.81;
const HEAD_BASE = 64.45;

/** The card, in layout pixels — before the plane tilts it. */
const CARD_W = 259.2;
const CARD_TOP = 79.8;
const GAP = 54.2;
const RADIUS = 10;
/**
 * The card runs to the foot of the frame — the rail is a surface passing
 * through the shot, not a row of objects sitting in it.
 *
 * Its own number rather than `REF_H - CARD_TOP`, because `CARD_TOP` is a
 * *layout* height on a tilted plane and the two are not the same measurement:
 * the plane pushes the card 54px down the frame on its way to the camera.
 */
const CARD_H = 323.3;
/** The picture's share of the card's width, as an aspect. */
const SHOT_ASPECT = 16 / 9;

/**
 * The plane.
 *
 * `HORIZON` is the height at which the plane is exactly life-size — above it the
 * rail is smaller and further away, below it nearer and larger. It is measured,
 * not chosen: solving the card's width at two heights puts it at 300.6, which is
 * most of the way down the visible card rather than at the frame's middle.
 */
const DEPTH = 740;
const TILT = 30;
const HORIZON = 300;

/**
 * The backdrop's axis, in degrees.
 *
 * Fitted, not guessed: a plane's corners have to satisfy TL + BR = TR + BL for a
 * linear gradient, and the recording's do to within five parts in 235 — so it is
 * linear, and the angle that puts its measured corners on one line is 138°.
 */
const ANGLE = 138;

/**
 * How far the rail travels, and the curve it travels on.
 *
 * One card pitch, so the rail comes to rest showing the next card where the last
 * one stood. The table is seconds → share of that distance, straight off the
 * recording: 29px on frame three, 2px a second later, and no analytic curve in
 * between that fits both ends.
 */
/**
 * Not `CARD_W + GAP`, and the difference is the point.
 *
 * A rail that advanced by exactly one pitch would be an assumption; measured, the
 * recording's travels 333 where its pitch is 325. A flick is a flick — it ends
 * where the momentum ran out, not on a snap — and eight pixels of overshoot is
 * the whole difference between a carousel and a surface someone pushed.
 */
const TRAVEL = 323;
const FLICK: readonly (readonly [number, number])[] = [
  [0, 0],
  [0.0333, 0.009],
  [0.0667, 0.0338],
  [0.1, 0.07508],
  [0.1333, 0.13213],
  [0.1667, 0.21021],
  [0.2, 0.2973],
  [0.225, 0.38138],
  [0.2583, 0.45345],
  [0.2917, 0.51351],
  [0.325, 0.56757],
  [0.3583, 0.60961],
  [0.3917, 0.65165],
  [0.4333, 0.68468],
  [0.4583, 0.71171],
  [0.4917, 0.73874],
  [0.525, 0.76276],
  [0.5583, 0.78378],
  [0.5917, 0.8018],
  [0.625, 0.81982],
  [0.6583, 0.83483],
  [0.6917, 0.84985],
  [0.73, 0.86186],
  [0.7633, 0.87387],
  [0.7967, 0.88288],
  [0.8383, 0.89189],
  [0.8717, 0.9009],
  [0.905, 0.90991],
  [0.9383, 0.91592],
  [0.9717, 0.92492],
  [0.9967, 0.93093],
  [1.03, 0.93694],
  [2.2, 1],
];

/** Linear read of a rising table, clamped at both ends. */
function read(
  table: readonly (readonly [number, number])[],
  x: number,
): number {
  const first = table[0];
  const last = table[table.length - 1];
  if (!first || !last) return 0;
  if (x <= first[0]) return first[1];
  if (x >= last[0]) return last[1];
  for (let i = 1; i < table.length; i++) {
    const hi = table[i];
    const lo = table[i - 1];
    if (hi && lo && x <= hi[0]) {
      return lo[1] + ((hi[1] - lo[1]) * (x - lo[0])) / (hi[0] - lo[0]);
    }
  }
  return last[1];
}

/** One card. Leave the words out and the picture is the whole card. */
export interface RailCard {
  image?: string;
  title?: string;
  /** A line of small print under the title. */
  note?: string;
  tag?: string;
}

export interface CardRailProps {
  /**
   * The cards, in order. The rail repeats them if it runs out.
   *
   * Also accepts one string, for the customizer and for quick edits: cards
   * split by `|`, and each card's picture, title, small print and tag split by
   * `>` — `"https://… > Inbox > 4 screens > @acme/inbox | https://…"`. A card
   * that is only a URL is only a picture. Not commas or `;`: a data: URL has
   * both.
   */
  cards?: readonly RailCard[] | string;
  /** The line that holds the top of the frame. */
  heading?: string;
  /** Frame the first flick starts on. Negative starts the scene already moving. */
  from?: number;
  /** How many flicks. Each one carries the rail about another card along. */
  flicks?: number;
  /** Frames between one flick leaving and the next. */
  every?: number;
  /** Where the rail sits before it moves, in layout pixels. */
  offset?: number;
  /**
   * The backdrop: two colour stops split by `|`, or one picture.
   *
   * A picture because a brand backdrop is often not a gradient at all — the
   * recording this was measured from has corners that satisfy a linear fit and a
   * middle that is 40 levels darker than one, which is a mesh or a painted plate
   * and not something two stops can be talked into.
   */
  backdrop?: string;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  fontFamily?: string;
}

function CardRailScene({
  cards = CardRailDefaults.cards,
  heading = "Browse templates",
  from = 0,
  flicks = 3,
  every = 30,
  offset = 0,
  backdrop = "",
  theme,
  mode = "light",
  fontFamily = "Default",
}: CardRailProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily) ?? SANS;

  const u = height / REF_H;
  const ox = (width - REF_W * u) / 2;

  const deck = toCards(cards);
  // No cards is a rail of blank ones, not a modulo by zero.
  const count = Math.max(1, deck.length);
  const stops = split(backdrop);
  const only = stops.length === 1 ? (stops[0] ?? "") : "";
  const plate = only.startsWith("data:") || only.startsWith("/") ? only : "";

  /**
   * Flicks add up.
   *
   * Each one is the same measured curve started `every` frames after the last,
   * and the rail's position is their sum — so a flick begun while the one before
   * it is still creeping carries that creep with it, which is what repeated
   * swipes actually do. `read` clamps at both ends, so a flick that has not
   * started contributes nothing and one that has finished contributes all of it.
   */
  let travelled = 0;
  for (let k = 0; k < Math.max(1, Math.round(flicks)); k++) {
    travelled += TRAVEL * read(FLICK, (frame - from - k * every) / fps);
  }
  const pitch = CARD_W + GAP;

  // Enough cards to cover the frame at its widest, plus one leaving and one
  // arriving. The rail repeats the list rather than running out.
  const span = Math.ceil(REF_W / pitch) + 3;
  // The rail has a beginning. Cards repeat to the right for as long as the flick
  // needs them, but nothing is drawn before the first one — a loop that wraps
  // round puts a card in the empty half of the frame the scene opens on.
  const first = Math.max(0, Math.floor((travelled - offset) / pitch));
  // The rail can show one card twice. Studio outlines the copy nearest the
  // middle of the frame; the other is only a picture of it.
  const nearest = new Map<number, number>();
  for (let n = 0; n < span; n++) {
    const i = first + n;
    const k = ((i % count) + count) % count;
    const d = Math.abs(i * pitch - travelled + offset - (REF_W - CARD_W) / 2);
    const held = nearest.get(k);
    const dHeld =
      held === undefined
        ? Number.POSITIVE_INFINITY
        : Math.abs(held * pitch - travelled + offset - (REF_W - CARD_W) / 2);
    if (d < dHeld) nearest.set(k, i);
  }

  // Both stops are mixed toward *blues*, never toward the page. The page is a
  // near-neutral, its hue in oklch is undefined, and interpolating the accent
  // through it comes out somewhere else entirely — measured once already, a blue
  // accent over a warm off-white mixed to a pale green.
  const from0 = stops[0] ?? mixOklch(t.primary, "#0b1f3d", 0.55);
  const to0 = stops[1] ?? mixOklch(t.primary, "#dceaff", 0.78);
  // A theme with a transparent page asks for no page: no backdrop, so the rail
  // sits on whatever is under it, and a heading in ink rather than mixed off it.
  const bare = parseColor(t.background).alpha === 0;

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={
        bare
          ? undefined
          : plate
            ? { backgroundColor: t.background }
            : { background: `linear-gradient(${ANGLE}deg, ${from0}, ${to0})` }
      }
    >
      {plate && !bare && (
        <Plate
          src={plate}
          style={{ position: "absolute", inset: 0, objectFit: "cover" }}
        />
      )}
      <div
        style={{
          position: "absolute",
          left: ox,
          top: 0,
          width: REF_W * u,
          height: REF_H * u,
          fontFamily: face,
          textRendering: "geometricPrecision",
          overflow: "hidden",
        }}
      >
        {heading && (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: (HEAD_BASE - HEAD_CAP * 1.32) * u,
              textAlign: "center",
              fontSize: HEAD_CAP * 1.38 * u,
              lineHeight: 1,
              fontWeight: 500,
              color: bare ? t.foreground : mixOklch(to0, t.background, 0.62),
            }}
          >
            {heading}
          </div>
        )}
        <div
          style={{
            position: "absolute",
            inset: 0,
            // The plane. `HORIZON` is where it is life-size, so the tilt pivots
            // about a line inside the visible band rather than about the top of
            // a box nobody can see.
            perspective: DEPTH * u,
            perspectiveOrigin: `50% ${HORIZON * u}px`,
          }}
        >
          <div
            style={{
              position: "absolute",
              inset: 0,
              transform: `rotateX(${TILT}deg)`,
              transformOrigin: `50% ${HORIZON * u}px`,
              transformStyle: "preserve-3d",
            }}
          >
            {Array.from({ length: span }, (_, n) => {
              const i = first + n;
              const x = i * pitch - travelled + offset;
              const k = ((i % count) + count) % count;
              const card = deck[k] ?? {};
              return (
                <Item key={i} index={k} primary={nearest.get(k) === i}>
                  <Card
                    x={x * u}
                    src={card.image ?? ""}
                    title={card.title ?? ""}
                    note={card.note ?? ""}
                    tag={card.tag ?? ""}
                    t={t}
                    u={u}
                  />
                </Item>
              );
            })}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
}

const split = (s: string) =>
  s
    .split("|")
    .map((v) => v.trim())
    .filter(Boolean);

/** The string form of `cards`: see `CardRailProps.cards`. */
function toCards(input: readonly RailCard[] | string): readonly RailCard[] {
  if (typeof input !== "string") return input;
  return input
    .split("|")
    .filter((c) => c.trim())
    .map((c) => {
      const [image = "", title = "", note = "", tag = ""] = c
        .split(">")
        .map((v) => v.trim());
      return { image, title, note, tag };
    });
}

/**
 * One card: a picture, and under it a title and a line of small print. Forwards
 * its `ref` and takes a `style` on top of its own so Remotion Studio can
 * outline it and nudge it (see `Item`) — forwardRef, not a `ref` prop, which
 * React 18 would drop.
 */
const Card = forwardRef<
  HTMLDivElement,
  {
    x: number;
    src: string;
    title: string;
    note: string;
    tag: string;
    t: KitTheme;
    u: number;
    style?: CSSProperties;
  }
>(function Card({ x, src, title, note, tag, t, u, style }, ref) {
  const bodied = Boolean(title || note || tag);
  const shot = CARD_W / SHOT_ASPECT;
  return (
    <div
      ref={ref}
      style={{
        ...style,
        position: "absolute",
        left: x,
        top: CARD_TOP * u,
        width: CARD_W * u,
        height: CARD_H * u,
        borderRadius: RADIUS * u,
