            }}
          >
            {title}
          </div>
          <div
            style={{
              marginTop: 5 * u,
              fontSize: 12.5 * u,
              lineHeight: 1.3,
              color: t.mutedForeground,
            }}
          >
            {note}
          </div>
          {tag && (
            <div
              style={{
                marginTop: 14 * u,
                display: "inline-block",
                padding: `${5 * u}px ${10 * u}px`,
                borderRadius: 999,
